#{noFlag} isPerpaid FROM FIN_CASH_INFO INNER JOIN FIN_CASH_PLAN ON FIN_CASH_PLAN.CASH_ID=FIN_CASH_INFO.CASH_ID INNER JOIN MST_FEEINFO ON FIN_CASH_INFO.FEE_ID=MST_FEEINFO.FEE_ID AND MST_FEEINFO.charge_type = #{chargeType} INNER JOIN BOK_POSITION_PRDFEE ON FIN_CASH_INFO.FINPROD_ID=BOK_POSITION_PRDFEE.FINPROD_ID AND FIN_CASH_INFO.BRANCH=BOK_POSITION_PRDFEE.BRANCH AND BOK_POSITION_PRDFEE.FEE_TYPE = FIN_CASH_INFO.CASH_TYPE_2 LEFT JOIN FIN_PRODUCT ON FIN_CASH_INFO.FINPROD_ID=FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN STL_FIN_PRODUCT_ACCT ON STL_FIN_PRODUCT_ACCT.FINPROD_ID=FIN_CASH_INFO.FINPROD_ID AND STL_FIN_PRODUCT_ACCT.CCY=FIN_CASH_INFO.CCY AND STL_FIN_PRODUCT_ACCT.ACCT_TYPE = '${acctType_trust}' LEFT JOIN PTL_PORTFOLIO_AUTHORITY ON FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID LEFT JOIN STL_FIN_PRODUCT_ACCT STL_FIN_PRODUCT_ACCT1 ON STL_FIN_PRODUCT_ACCT1.FINPROD_ID=FIN_CASH_INFO.FINPROD_ID AND STL_FIN_PRODUCT_ACCT1.CCY=FIN_CASH_INFO.CCY AND STL_FIN_PRODUCT_ACCT1.CASH_ID = FIN_CASH_INFO.CASH_ID WHERE FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} AND BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP >0 AND FIN_CASH_PLAN.MDATE <= #{platDate} AND FIN_PRODUCT.P_FINPROD_ID is null and not exists (select 1 from TRD_PRODUCT_DEAL where FIN_CASH_PLAN.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID and FIN_CASH_PLAN.MDATE = TRD_PRODUCT_DEAL.MDATE AND FIN_CASH_PLAN.BRANCH=TRD_PRODUCT_DEAL.BRANCH AND BOK_POSITION_PRDFEE.FEE_TYPE=TRD_PRODUCT_DEAL.FINPROD_TYPE2 and TRD_PRODUCT_DEAL.IS_CANCEL = #{noFlag} and TRD_PRODUCT_DEAL.TRADE_STATUS = #{tradeStatus}) AND BOK_POSITION_PRDFEE.CDATE =
(SELECT MAX(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND B.BRANCH = BOK_POSITION_PRDFEE.BRANCH AND B.FEE_TYPE = BOK_POSITION_PRDFEE.FEE_TYPE AND B.CDATE < FIN_CASH_PLAN.MDATE )
and (FIN_PRODUCT_ADD.PORTFOLIO_ID in
null) OR FIN_PRODUCT_ADD.PORTFOLIO_ID in(
#{item} )
