/*新增费用类型检索 guyunfei 20190923 end*/
and PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}

select '${pendingStatus}' effectStatus,
FIN_PRODUCT_ADD.PORTFOLIO_ID ptlId, FIN_PRODUCT1.FINPROD_MARKET_ID finprodMarketId, FIN_PRODUCT1.Finprod_Id finprodId, FIN_PRODUCT_ADD.SALE_DEPARTMENT saleDepartment, MST_FEEINFO.FEE_ID feeId, MST_FEEINFO.Fee_Name feeName, BOK_POSITION_PRDFEE.FEE_TYPE feeType,
