and FIN_CASH_PLAN.PAY_DATE >= to_date(#{payDateStart}, 'yyyy-MM-dd')
and FIN_CASH_PLAN.PAY_DATE <= to_date(#{payDateEnd}, 'yyyy-MM-dd')
and STL_FIN_PRODUCT_ACCT1.ACCT_NO in
#{item}
