SELECT TEMP.finprodMarketId finprodMarketId, TEMP.finprodId finprodId, TEMP.sFinprodId sFinprodId, TEMP.feeId feeId, sys_datadict_list.item_value basicBill, TEMP.feeName feeName, TEMP.feeType feeType, TEMP.calcStartDate calcStartDate, TEMP.calcEndDate calcEndDate, TEMP.ccy ccy, TEMP.actPayAmt actPayAmt, TEMP.payAmt payAmt FROM( SELECT FIN_PRODUCT_ADD.PORTFOLIO_ID finprodMarketId ,FIN_PRODUCT.Finprod_Id finprodId ,NULL as sFinprodId ,MST_FEEINFO.FEE_ID feeId ,MST_FEEINFO.BASIC_BILL basicBill ,MST_FEEINFO.Fee_Name feeName ,BOK_POSITION_PRDFEE.FEE_TYPE feeType ,TRD_PRODUCT_DEAL.MDATE as calcStartDate
,CASE WHEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') THEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE ELSE to_date(#{calcEndDate}, 'yyyy-MM-dd') END as calcEndDate ,FIN_CASH_INFO.ccy ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as actPayAmt ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as payAmt FROM FIN_CASH_INFO INNER JOIN FIN_CASH_PAY_RULE ON FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
AND FIN_CASH_PAY_RULE.PAY_CYCLE != #{payCycle}
AND FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}
INNER JOIN MST_FEEINFO ON FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID AND MST_FEEINFO.CHARGE_TYPE IN(#{chargeType}) INNER JOIN BOK_POSITION_PRDFEE ON FIN_CASH_INFO.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND FIN_CASH_INFO.BRANCH = BOK_POSITION_PRDFEE.BRANCH and FIN_CASH_INFO.CASH_TYPE_2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN (select FINPROD_ID, BRANCH, FINPROD_TYPE2, mdate from (select d.*, row_number() over(partition by FINPROD_ID, BRANCH, FINPROD_TYPE2 order by MDATE desc) as rnum from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.IS_CANCEL = #{isCancel} AND d.TRADE_STATUS = #{tradeStatus_01} and MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') ) t where rnum = 1)TRD_PRODUCT_DEAL on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH AND TRD_PRODUCT_DEAL.FINPROD_TYPE2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN FIN_PRODUCT ON FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN FIN_FLOAT_COUNTING_RULE ON FIN_FLOAT_COUNTING_RULE.CASH_ID = FIN_CASH_INFO.CASH_ID WHERE FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} AND FIN_PRODUCT.P_FINPROD_ID is null AND FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId} AND FIN_PRODUCT.FINPROD_ID = #{finprodId} AND MST_FEEINFO.FEE_ID = #{feeId} AND BOK_POSITION_PRDFEE.CDATE = (SELECT max(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND B.BRANCH = BOK_POSITION_PRDFEE.BRANCH AND BOK_POSITION_PRDFEE.FEE_TYPE = B.FEE_TYPE AND B.CDATE <to_date(#{calcEndDate}, 'yyyy-MM-dd')) UNION SELECT FIN_PRODUCT_ADD.PORTFOLIO_ID finprodMarketId ,FIN_PRODUCT1.FINPROD_MARKET_ID finprodId ,FIN_PRODUCT.FINPROD_ID as sFinprodId ,MST_FEEINFO.FEE_ID feeId ,MST_FEEINFO.BASIC_BILL basicBill ,MST_FEEINFO.Fee_Name feeName ,BOK_POSITION_PRDFEE.FEE_TYPE feeType ,TRD_PRODUCT_DEAL.MDATE as calcStartDate
,CASE WHEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') THEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE ELSE to_date(#{calcEndDate}, 'yyyy-MM-dd') END as calcEndDate
,FIN_CASH_INFO.ccy ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as actPayAmt ,BOK_POSITION_PRDFEE.TDY_UNPAID_INTINCEXP as payAmt FROM FIN_CASH_INFO INNER JOIN FIN_CASH_PAY_RULE ON FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID
AND FIN_CASH_PAY_RULE.PAY_CYCLE != #{payCycle}
AND FIN_CASH_PAY_RULE.PAY_CYCLE = #{payCycle}
INNER JOIN MST_FEEINFO ON FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID AND MST_FEEINFO.CHARGE_TYPE IN(#{chargeType}) INNER JOIN BOK_POSITION_PRDFEE ON FIN_CASH_INFO.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND FIN_CASH_INFO.BRANCH = BOK_POSITION_PRDFEE.BRANCH and FIN_CASH_INFO.CASH_TYPE_2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN (select FINPROD_ID, BRANCH, FINPROD_TYPE2, mdate from (select d.*, row_number() over(partition by FINPROD_ID, BRANCH, FINPROD_TYPE2 order by MDATE desc) as rnum from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.IS_CANCEL = #{isCancel} AND d.TRADE_STATUS = #{tradeStatus_01} and MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') ) t where rnum = 1)TRD_PRODUCT_DEAL on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH AND TRD_PRODUCT_DEAL.FINPROD_TYPE2 = BOK_POSITION_PRDFEE.FEE_TYPE LEFT JOIN FIN_PRODUCT ON FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT.FINPROD_ID LEFT JOIN FIN_PRODUCT FIN_PRODUCT1 ON BOK_POSITION_PRDFEE.FINPROD_ID = FIN_PRODUCT1.FINPROD_ID
LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT1.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID LEFT JOIN FIN_FLOAT_COUNTING_RULE ON FIN_FLOAT_COUNTING_RULE.CASH_ID = FIN_CASH_INFO.CASH_ID WHERE FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} AND FIN_PRODUCT.P_FINPROD_ID is not null AND FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId} AND FIN_PRODUCT.P_FINPROD_ID = #{finprodId} AND MST_FEEINFO.FEE_ID = #{feeId} AND BOK_POSITION_PRDFEE.CDATE = (SELECT max(B.CDATE) FROM BOK_POSITION_PRDFEE B WHERE B.FINPROD_ID = BOK_POSITION_PRDFEE.FINPROD_ID AND B.BRANCH = BOK_POSITION_PRDFEE.BRANCH AND BOK_POSITION_PRDFEE.FEE_TYPE = B.FEE_TYPE
AND B.CDATE <to_date(#{calcEndDate}, 'yyyy-MM-dd'))
AND FIN_CASH_INFO.CASH_ID = #{cashId}
union all
select PTL_PORTFOLIO.PORTFOLIO_ID finprodMarketId ,FIN_PRODUCT_ADD.FINPROD_ID finprodId ,'' as sFinprodId ,MST_FEEINFO.FEE_ID feeId ,MST_FEEINFO.BASIC_BILL basicBill ,MST_FEEINFO.Fee_Name feeName ,PTL_FEE_POSITION.PTL_FEE_TYPE feeType ,nvl(TRD_PRODUCT_DEAL.MDATE,PTL_PORTFOLIO.vdate) as calcStartDate
,CASE WHEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') THEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE ELSE to_date(#{calcEndDate}, 'yyyy-MM-dd') END as calcEndDate
,FIN_CASH_INFO.ccy ,PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE as actPayAmt ,PTL_FEE_POSITION.TDY_ACCUMUL_PAY_FEE as payAmt from PTL_FEE_POSITION, FIN_PRODUCT_ADD, PTL_PORTFOLIO ,MST_FEEINFO, FIN_CASH_INFO LEFT JOIN (select FINPROD_ID, BRANCH, FINPROD_TYPE2, mdate from (select d.*, row_number() over(partition by FINPROD_ID, BRANCH, FINPROD_TYPE2 order by MDATE desc) as rnum from TRD_PRODUCT_DEAL d where d.PS = #{ps} AND d.IS_CANCEL = #{isCancel} AND d.TRADE_STATUS = #{tradeStatus_01} and MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') ) t where rnum = 1)TRD_PRODUCT_DEAL on FIN_CASH_INFO.FINPROD_ID = TRD_PRODUCT_DEAL.FINPROD_ID AND FIN_CASH_INFO.BRANCH = TRD_PRODUCT_DEAL.BRANCH and FIN_CASH_INFO.CASH_TYPE_2 = TRD_PRODUCT_DEAL.FINPROD_TYPE2 LEFT JOIN FIN_FLOAT_COUNTING_RULE ON FIN_FLOAT_COUNTING_RULE.CASH_ID = FIN_CASH_INFO.CASH_ID where PTL_FEE_POSITION.PORTFOLIO_ID = FIN_PRODUCT_ADD.PORTFOLIO_ID and FIN_PRODUCT_ADD.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID and FIN_CASH_INFO.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID and FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1} and FIN_CASH_INFO.CASH_TYPE_2 = #{cashType2_C04} and FIN_CASH_INFO.FEE_ID = MST_FEEINFO.FEE_ID and PTL_FEE_POSITION.PTL_FEE_TYPE = FIN_CASH_INFO.CASH_TYPE_2 AND MST_FEEINFO.CHARGE_TYPE = #{chargeType} and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId} and PTL_FEE_POSITION.PTL_FEE_TYPE = #{feeType} and PTL_FEE_POSITION.CDATE = to_date(#{calcEndDate}, 'yyyy-MM-dd') - 1 and PTL_PORTFOLIO.PROFIT_TYPE = #{profitType}
union all select distinct pp.PORTFOLIO_ID finprodMarketId ,fpa.FINPROD_ID finprodId ,'' as sFinprodId ,MST_FEEINFO.FEE_ID feeId ,MST_FEEINFO.BASIC_BILL basicBill ,MST_FEEINFO.Fee_Name feeName ,#{feeType} feeType ,nvl(payd.MDATE,pp.vdate) as calcStartDate ,CASE WHEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') THEN FIN_FLOAT_COUNTING_RULE.E_ACCR_DATE ELSE to_date(#{calcEndDate}, 'yyyy-MM-dd') END as calcEndDate
,MST_FEEINFO.ccy ,nvl(td.sumintamt,0)-nvl(payd.sumfeepay,0) as actPayAmt ,nvl(td.sumintamt,0)-nvl(payd.sumfeepay,0) as payAmt from (select tpd.finprod_id as finprod_id,sum(nvl(tpd.int_amt,0)) as sumintamt from trd_product_deal tpd where tpd.busi_type='34' and tpd.trade_date < to_date(#{calcEndDate}, 'yyyy-MM-dd') group by tpd.finprod_id ) td inner join FIN_PRODUCT fp on td.finprod_id=fp.finprod_id inner join FIN_PRODUCT_ADD fpa on fpa.finprod_id=nvl(fp.p_finprod_id,fp.finprod_id) inner join PTL_PORTFOLIO pp on fpa.PORTFOLIO_ID = pp.PORTFOLIO_ID left join ( select d.finprod_id,sum(decode(d.is_clean,'Y',nvl(pd.theory_int,0),nvl(d.trade_amt,0))) as sumfeepay , max(d.mdate) as mdate from trd_product_deal d inner join trd_trade_fee_detail ttd on d.trade_id=ttd.trade_id inner join pa_trd_product_deal pd on d.trade_id=pd.trade_id where ttd.fee_id= #{feeId} and d.ps= #{ps} and d.finprod_type2=#{cashType2_C04} AND d.IS_CANCEL =#{isCancel} AND d.TRADE_STATUS =#{tradeStatus_01} and d.MDATE < to_date(#{calcEndDate}, 'yyyy-MM-dd') group by d.finprod_id
)payd on fpa.finprod_id = payd.finprod_id left join (select mst1.fee_id,mst1.BASIC_BILL,mst1.Fee_Name,fc1.ccy,fc1.cash_id,fpa1.PORTFOLIO_ID from MST_FEEINFO mst1 inner join FIN_CASH_INFO fc1 on mst1.fee_id=fc1.fee_id and fc1.cash_type_1= #{cashType1} and fc1.CASH_TYPE_2 = #{cashType2_C04} and fc1.finprod_type='01' inner join FIN_PRODUCT fp1 on fc1.finprod_id=fp1.finprod_id inner join fin_product_add fpa1 on fp1.finprod_id=fpa1.finprod_id where mst1.fee_id=#{feeId} and fpa1.PORTFOLIO_ID=#{ptlId} ) mst_feeinfo on fpa.PORTFOLIO_ID=mst_feeinfo.PORTFOLIO_ID LEFT JOIN FIN_FLOAT_COUNTING_RULE ON FIN_FLOAT_COUNTING_RULE.CASH_ID = mst_feeinfo.CASH_ID where fpa.finprod_id = 'F16_'||#{ptlId} and fpa.is_cycle='Y'
)TEMP left join sys_datadict_list on TEMP.basicBill = sys_datadict_list.item_code and dict_code = 'BILL_BASE_FEE_KIND'

select FIN_PRODUCT.CCY as ccy , FIN_PRODUCT.FINPROD_ID as finprodId, FIN_PRODUCT.PROFIT_TYPE as profitType, FIN_PRODUCT_ADD.DEAL_MODE as dealMode, FIN_PRODUCT.MDATE, mdate from FIN_PRODUCT, FIN_PRODUCT_ADD /*, PA_FIN_PRODUCT*/ where FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID /*AND FIN_PRODUCT.FINPROD_ID = PA_FIN_PRODUCT.FINPROD_ID*/
and FIN_PRODUCT_ADD.PORTFOLIO_ID = #{ptlId}
AND rownum = 1 order by FIN_PRODUCT.FINPROD_ID /* add by songyawei 20200713 */


    select sum(PTPD.THEORY_AMT)-sum(TTFD.FEE_AMT) from 
    PA_TRD_PRODUCT_DEAL PTPD ,TRD_TRADE_FEE_DETAIL TTFD,TRD_PRODUCT_DEAL TPD,FIN_PRODUCT_ADD FPA
		WHERE TTFD.TRADE_ID = PTPD.TRADE_ID
		AND TPD.TRADE_ID = PTPD.TRADE_ID
		AND FPA.FINPROD_ID = TPD.FINPROD_ID
