and add1.trade_id=deal.trade_id and add1.portfolio_id=#{ptlId}  and deal.trade_date <= to_date(#{cdate}, 'yyyy-MM-dd') and deal.finprod_id=prod.finprod_id and prod.REGIST_ORG=#{org}
)

  select nvl(sum(nvl(trade_amt,0)),0) from  trd_product_deal deal,trd_product_deal_add add1 ,
mst_feeinfo fee,fin_product prod,TRD_TRADE_FEE_DETAIL feed
 where  
 deal.finprod_id=prod.finprod_id 
